function Paths() {
  return (
    <>
      {LOGO_PATHS.map((d, i) => (
        <path key={i} d={d} />
      ))}
    </>
  );
}

/** The complete mark. Extra props land on the <svg> (style, data-*, …). */
export default function LogoMark({
  className,
  ...rest
}: React.SVGProps<SVGSVGElement>) {
  return (
    <svg
      viewBox={LOGO_VIEWBOX}
      className={className}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      {...rest}
    >
      <Paths />
    </svg>
  );
}

/** Hidden definition of the mark, so copies of it cost nothing extra. */
export function LogoSprite({ id }: { id: string }) {
  return (
    <svg width="0" height="0" aria-hidden="true" style={{ position: "absolute" }}>
      <defs>
        <g id={id}>
          <Paths />
        </g>
      </defs>
    </svg>
  );
}

/** A full-size instance of the sprite. The caller clips it to a half. */
export function LogoHalf({
  spriteId,
  className,
}: {
  spriteId: string;
  className?: string;
}) {
  return (
    <svg
      viewBox={LOGO_VIEWBOX}
      className={className}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
    >
      <use href={`#${spriteId}`} />
    </svg>
  );
}
